DELIMITER $$
CREATE PROCEDURE pending_repairs()
BEGIN
SELECT prj_num,prj_name,start_date FROM Salvaging WHERE end_date IS NULL ORDER BY prj_num;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE supplies_by_spec(IN p_spec VARCHAR(20))
BEGIN
SELECT mat_num,mat_name,amount FROM Stock WHERE speci=p_spec ORDER BY mat_num;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE issued_units(IN p_material CHAR(4), OUT p_total INT)
BEGIN
SELECT COALESCE(SUM(amount),0) INTO p_total FROM Out_stock WHERE mat_num=p_material;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE stock_band(IN p_material CHAR(4), OUT p_band VARCHAR(12))
BEGIN
DECLARE n INT DEFAULT NULL;
SET n=(SELECT amount FROM Stock WHERE mat_num=p_material);
IF n IS NULL THEN SET p_band='unknown';
ELSEIF n<50 THEN SET p_band='low';
ELSE SET p_band='ready';
END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE PROCEDURE warehouse_chain(OUT p_chain VARCHAR(400))
BEGIN
DECLARE finished BOOL DEFAULT FALSE;
DECLARE wh VARCHAR(20);
DECLARE warehouses CURSOR FOR SELECT DISTINCT warehouse FROM Stock WHERE warehouse IS NOT NULL ORDER BY warehouse;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished=TRUE;
SET p_chain='';
OPEN warehouses;
read_warehouses: LOOP
  FETCH warehouses INTO wh;
  IF finished THEN LEAVE read_warehouses; END IF;
  SET p_chain=IF(p_chain='',wh,CONCAT(p_chain,'|',wh));
END LOOP;
CLOSE warehouses;
END$$
DELIMITER ;
